package br.com.axecloud.app.feature.library
import android.net.Uri
import androidx.lifecycle.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject
@HiltViewModel class LibraryViewModel @Inject constructor(private val repo:LibraryRepository):ViewModel(){private val mutable=MutableStateFlow(LibraryUiState());val state=mutable.asStateFlow();init{load()};fun load()=viewModelScope.launch{mutable.update{it.copy(loading=true,error=null)};runCatching{repo.load()}.onSuccess{(f,d)->mutable.update{it.copy(loading=false,isFilho=f,materials=d)}}.onFailure{e->mutable.update{it.copy(loading=false,error=e.message)}}};fun query(v:String)=mutable.update{it.copy(query=v)};fun category(v:String)=mutable.update{it.copy(category=v)};fun openUpload()=mutable.update{it.copy(uploadOpen=true)};fun closeUpload()=mutable.update{it.copy(uploadOpen=false,error=null)};fun consume()=mutable.update{it.copy(message=null)};fun select(m:LibraryMaterial?){if(m==null)mutable.update{it.copy(selected=null,comments=emptyList(),error=null)}else viewModelScope.launch{mutable.update{it.copy(selected=m,loadingComments=true,error=null)};runCatching{repo.comments(m.id)}.onSuccess{(comments,user,manager)->mutable.update{it.copy(loadingComments=false,comments=comments,currentUserId=user,manager=manager)}}.onFailure{e->mutable.update{it.copy(loadingComments=false,error=e.message)}}}};fun sendComment(text:String,parentId:String?=null)=viewModelScope.launch{val material=mutable.value.selected?:return@launch;mutable.update{it.copy(sendingComment=true,error=null)};runCatching{repo.comment(material.id,text,parentId);repo.comments(material.id)}.onSuccess{(comments,user,manager)->mutable.update{it.copy(sendingComment=false,comments=comments,currentUserId=user,manager=manager,message="Mensagem publicada no estudo.")}}.onFailure{e->mutable.update{it.copy(sendingComment=false,error=e.message)}}};fun deleteComment(id:String)=viewModelScope.launch{val material=mutable.value.selected?:return@launch;mutable.update{it.copy(actionId=id,error=null)};runCatching{repo.deleteComment(id);repo.comments(material.id)}.onSuccess{(comments,user,manager)->mutable.update{it.copy(actionId=null,comments=comments,currentUserId=user,manager=manager,message="Comentário excluído.")}}.onFailure{e->mutable.update{it.copy(actionId=null,error=e.message)}}};fun upload(uri:Uri,title:String,category:String)=viewModelScope.launch{mutable.update{it.copy(uploading=true,error=null)};runCatching{repo.upload(uri,title,category);repo.load()}.onSuccess{(f,d)->mutable.update{it.copy(uploading=false,uploadOpen=false,isFilho=f,materials=d,message="Material publicado.")}}.onFailure{e->mutable.update{it.copy(uploading=false,error=e.message)}}};fun delete(m:LibraryMaterial)=viewModelScope.launch{mutable.update{it.copy(actionId=m.id,error=null)};runCatching{repo.delete(m.id)}.onSuccess{mutable.update{it.copy(actionId=null,materials=it.materials.filterNot{r->r.id==m.id},message="Material excluído.")}}.onFailure{e->mutable.update{it.copy(actionId=null,error=e.message)}}}}
